import { Card, CardContent } from "@/registry/erbium/ui/card";
import {
  Carousel,
  CarouselNext,
  CarouselPrevious,
  CarouselSlide,
  CarouselSlides,
} from "@/registry/erbium/ui/carousel";

const CarouselDemo = () => (
  <Carousel aria-label="Numbers" className="w-full max-w-xs">
    <CarouselSlides>
      {Array.from({ length: 5 }, (_, index) => (
        <CarouselSlide key={index}>
          <Card className="aspect-square">
            <CardContent className="flex min-h-0 flex-1 items-center justify-center">
              <span className="text-display font-semibold">{index + 1}</span>
            </CardContent>
          </Card>
        </CarouselSlide>
      ))}
    </CarouselSlides>
    <CarouselPrevious />
    <CarouselNext />
  </Carousel>
);

export default CarouselDemo;

import Demo from "../examples/carousel-demo";

const Example = () => (
  <div className="w-full min-w-72 max-w-2xl p-4">
    <Demo />
  </div>
);

export default Example;
